pub(crate) fn assert_authorized_record(cwd: &Path, cid: &str, authorization: &str) {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(entries)) = decode_node(&store.get_canonical(cid).unwrap()).unwrap()
    else {
        panic!("activation record must be a value map")
    };
    assert_eq!(
        field(&entries, "schema"),
        &Value::Text("unicodex.module_activation_record.v2".to_owned())
    );
    assert_eq!(
        field(&entries, "activation_authorization"),
        &Value::Ref(authorization.to_owned())
    );
}

pub(crate) fn forge_relation(cwd: &Path, cid: &str, relation: &str) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(cid).unwrap()).unwrap()
    else {
        panic!("authorization must be a value map")
    };
    entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text("allowed_behavior_relation".to_owned()))
        .unwrap()
        .1 = Value::Text(relation.to_owned());
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}

fn field<'a>(entries: &'a [(Value, Value)], key: &str) -> &'a Value {
    entries
        .iter()
        .find_map(|(name, value)| (name == &Value::Text(key.to_owned())).then_some(value))
        .unwrap()
}

pub(crate) fn text(value: &JsonValue, field: &str) -> String {
    value[field].as_str().unwrap().to_owned()
}

pub(crate) fn pointer_text(value: &JsonValue, pointer: &str) -> String {
